import{_ as n,c as i,o as r,ah as t}from"./chunks/framework.CDiWxQbG.js";const c=JSON.parse('{"title":"Teil A – Anwenderhandbuch","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/index.md","filePath":"manual/teil-a-anwenderhandbuch/index.md"}'),a={name:"manual/teil-a-anwenderhandbuch/index.md"};function s(h,e,d,l,u,o){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="teil-a-–-anwenderhandbuch" tabindex="-1">Teil A – Anwenderhandbuch <a class="header-anchor" href="#teil-a-–-anwenderhandbuch" aria-label="Permalink to &quot;Teil A – Anwenderhandbuch&quot;">​</a></h1><p>Dieser Teil des Handbuchs richtet sich an Anwender*Innen, die Qonnectra im täglichen Betrieb nutzen. Dazu gehören insbesondere Mitarbeitende in Verwaltungen, Zweckverbänden, Stadtwerken sowie Entscheidungsträger*Innen und externe Stellen mit Leserechten.</p><p>In Teil A wird ausschließlich die Arbeit mit der <strong>Webanwendung</strong> beschrieben. Es sind <strong>keine GIS-Kenntnisse erforderlich</strong>. Alle hier dargestellten Funktionen können sicher über den Webbrowser genutzt werden.</p><p>Themen wie Systemadministration, QGIS-Nutzung oder technische Einrichtung sind nicht Bestandteil dieses Teils und werden in den folgenden Abschnitten behandelt.</p><h2 id="ziele-der-dokumentation" tabindex="-1">Ziele der Dokumentation <a class="header-anchor" href="#ziele-der-dokumentation" aria-label="Permalink to &quot;Ziele der Dokumentation&quot;">​</a></h2><p>Die <strong>Webanwendung</strong> dient der strukturierten Einsicht, Dokumentation und Auswertung des Netzbestands. Sie ist bewusst reduziert gestaltet, um auch ohne GIS-Vorkenntnisse genutzt werden zu können, und bereitet Trassen, Verlegearten, Oberflächen, Netzebenen, Netzknoten und Gewährleistungsstände projektbezogen auf. Der Fokus liegt dabei auf drei Zielen:</p><ul><li><strong>Transparenz schaffen</strong> über den dokumentierten Ausbauzustand,</li><li><strong>Wissen sichern</strong>, etwa für Rückfragen von Ämtern, beteiligten Organisationen oder Förderinstitutionen,</li><li><strong>Komplexität reduzieren</strong> durch eine klare, nicht überladene Benutzeroberfläche.</li></ul><h2 id="ansehen-und-bearbeiten" tabindex="-1">Ansehen und Bearbeiten <a class="header-anchor" href="#ansehen-und-bearbeiten" aria-label="Permalink to &quot;Ansehen und Bearbeiten&quot;">​</a></h2><p>Reine Ansichten sind das Dashboard, das den Bestand auswertet, sowie die Störungsanalyse, die Wertermittlung und der Faserweg, die auf den Daten rechnen, ohne sie zu ändern. In der Karte lesen Sie die Eigenschaften der Objekte; bearbeiten können Sie dort ausschließlich ihre Anhänge. Anlegen und bearbeiten können Sie</p><ul><li>Rohre und ihre Eigenschaften in der <strong>Rohrverwaltung</strong>, dort auch den Status der Mikrorohre, siehe Kapitel <a href="./10-rohrverwaltung.html">Rohrverwaltung</a>,</li><li>die Zuordnung von Rohren zu Trassensegmenten in der <strong>Rohrzuordnung</strong>, siehe Kapitel <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>,</li><li>die Verbindungen der Mikrorohre in der <strong>Rohrverzweigung</strong>, siehe Kapitel <a href="./12-rohrverzweigung.html">Rohrverzweigung</a>,</li><li>die Netzknoten an den Mikrorohren eines Hausanschlusses, siehe Kapitel <a href="./13-mikrorohre.html">Mikrorohre</a>,</li><li>Netzknoten, Kabel und deren Aufbau im <strong>Netzschema</strong>, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>,</li><li>Adressen und ihre Wohneinheiten, siehe Kapitel <a href="./16-adressen.html">Adressen</a>,</li><li>den Ausbaustatus einer Adresse in der <strong>Nachverdichtung</strong>, siehe Kapitel <a href="./07-nachverdichtung.html">Nachverdichtung</a>,</li><li>Auskünfte und ihre Auskunftsbereiche in der <strong>Leitungsauskunft</strong>, siehe Kapitel <a href="./08-leitungsauskunft.html">Leitungsauskunft</a>,</li><li>Anhänge (Dateien) an Kartenobjekten, an Rohren und an Adressen, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a>.</li></ul><p>Die <strong>Geometrie</strong> – der Verlauf einer Trasse, die Lage eines Netzknotens oder der Zuschnitt eines Gebiets – wird nicht in der Webanwendung bearbeitet, sondern in QGIS. Beide greifen auf dieselbe Datenbasis zu; das Vorgehen beschreibt Kapitel <a href="./../teil-b-betrieb-admin-qgis/26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a> in Teil B.</p><h2 id="ein-typischer-arbeitsablauf" tabindex="-1">Ein typischer Arbeitsablauf <a class="header-anchor" href="#ein-typischer-arbeitsablauf" aria-label="Permalink to &quot;Ein typischer Arbeitsablauf&quot;">​</a></h2><p>Für den Einstieg hat sich die folgende Reihenfolge bewährt:</p><ol><li>Melden Sie sich an und machen Sie sich mit dem Aufbau der Oberfläche vertraut, siehe Kapitel <a href="./01-erste-schritte.html">Erste Schritte</a>.</li><li>Wählen Sie oben links in der Kopfzeile das Projekt aus, mit dem Sie arbeiten möchten, siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>.</li><li>Verschaffen Sie sich im Dashboard einen Überblick über den Ausbauzustand, siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>.</li><li>Sehen Sie sich einzelne Objekte in der Karte an und rufen Sie deren Eigenschaften und Anhänge ab, siehe Kapitel <a href="./05-karte.html">Karte</a>.</li><li>Pflegen Sie Rohre in der Rohrverwaltung und ordnen Sie sie anschließend den Trassensegmenten zu, siehe Kapitel <a href="./10-rohrverwaltung.html">Rohrverwaltung</a> und <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>.</li></ol><p>Die Kapitel 4 bis 17 von Teil A folgen der linken Navigationsleiste von oben nach unten. Die Kapitel 1 bis 3 stehen davor, weil die übrigen darauf aufbauen.</p>',15)])])}const g=n(a,[["render",s]]);export{c as __pageData,g as default};
